        test("generic attachment send proof uses exact filename plus post-baseline fallback and composer-clean MAIN-world click",()->{String adapter=Files.readString(Path.of("chatgpt-bridge-extension/src/chatgpt-adapter.js"),StandardCharsets.UTF_8),background=Files.readString(Path.of("chatgpt-bridge-extension/src/background.js"),StandardCharsets.UTF_8),content=Files.readString(Path.of("chatgpt-bridge-extension/src/content.js"),StandardCharsets.UTF_8),manifest=Files.readString(Path.of("chatgpt-bridge-extension/manifest.json"),StandardCharsets.UTF_8);ok(adapter.contains("attachmentTurnPresent"),"generic exact-filename attachment-turn confirmation helper is missing");ok(adapter.contains("postBaselineUserTurnPresent"),"post-baseline user-turn fallback confirmation is missing");ok(adapter.contains("slice(prepared.beforeUserMessages)"),"strong outgoing confirmation is not scoped after the delivery baseline");ok(adapter.contains("userTurnSurface(message)"),"strong post-Send proof is still restricted to the message-author node");ok(adapter.contains("conversation-turn-"),"strong post-Send proof does not prefer a complete ChatGPT conversation-turn container");ok(adapter.contains("ownsOnlyAuthoredMessage(turn, message)"),"preferred conversation-turn/article candidate bypasses authored-turn ownership guard");ok(adapter.contains("!ownsOnlyAuthoredMessage(parent, message)"),"strong fallback can cross into a neighboring authored turn");ok(adapter.contains("attachmentTurnCandidates(turn).some(node => nodeShowsFileName(node, prepared.fileName))"),"strong exact-filename attachment-surface proof disappeared");ok(adapter.contains("!present && postBaselineTurnPresent"),"Sent fallback does not require the prepared composer attachment to have left");ok(adapter.contains("attachment-filename-surface"),"generic stronger proof mode is not exposed");ok(adapter.contains("post-baseline-user-turn"),"fallback proof mode is not exposed");ok(adapter.contains("state: \"contaminated\""),"content-side composer contamination state is missing");ok(content.contains("post-baseline user turn appeared"),"Sent diagnostic does not describe fallback confirmation");ok(content.contains("no post-baseline user turn could be confirmed"),"UnknownAfterSend diagnostic does not describe the remaining uncertainty boundary");ok(content.contains("Math.min(milliseconds, 10000)"),"post-click missing-attachment grace is still fixed too short");ok(background.contains("composer-dirty"),"MAIN-world Send click does not reject later composer text");int armCall=content.indexOf("if (!possibleSendRecorded) await onSendArmed();"),attempt=content.indexOf("OBS_ATTACHMENT_SEND_ATTEMPT",armCall),noClick=content.indexOf("else if (!possibleSendRecorded) await onSendNotClicked();",attempt),sendStage=content.indexOf("stageTask(task, \"SendClicked\")",attempt);ok(armCall>=0&&attempt>armCall&&noClick>attempt&&sendStage>attempt,"generic Send attempt does not authorize the first possible click and preserve explicit no-click/click stages");ok(manifest.contains("\"version\": \"0.4.2\""),"extension patch version was not advanced for event-driven chat-context timeout correction");});
        test("ReviewDiff DOM turn-boundary and fallback regression is wired into the standard test runner",()->{String runner=Files.readString(Path.of("run-tests.cmd"),StandardCharsets.UTF_8),domTest=Files.readString(Path.of("chatgpt-bridge-extension/test/chatgpt-adapter-dom.test.js"),StandardCharsets.UTF_8);ok(runner.contains("node chatgpt-bridge-extension\\test\\chatgpt-adapter-dom.test.js"),"standard test runner does not execute the DOM regression");ok(domTest.contains("same-turn sibling attachment file card was not accepted"),"positive same-turn DOM regression is missing");ok(domTest.contains("neighboring attachment crossed the authored-turn boundary"),"negative neighboring-turn DOM regression is missing");ok(domTest.contains("ordinary filename message text was treated as attachment proof"),"ordinary-text negative DOM regression is missing");ok(domTest.contains("snapshot ZIP filename surface was not accepted"),"generic Snapshot filename proof regression is missing");ok(domTest.contains("post-baseline user-turn fallback did not confirm Send"),"fallback Send-confirmation regression is missing");ok(domTest.contains("missing attachment without a post-baseline user turn was falsely confirmed as Sent"),"fallback uncertainty regression is missing");});
