        test("default snapshot handoff is fingerprinted and attach-only",()->{StateStore st=new StateStore(tmp.resolve("snapshot-state"));ChatBridgeService s=serviceWithChat(st,"convG2345678",141);Path zip=snapshotZip(tmp.resolve("snapshot.zip"));Core.ChatTaskInfo info=s.enqueueSnapshot(zip,"convG2345678");ok(!info.autoSend(),"snapshot requested auto send");Map<String,Object> claim=s.claim("convG2345678",141);ChatBridgeService.PayloadSource source=s.verifiedPayloadSource(info.taskId(),ticket(claim));eq(source.sha256(),claim.get("artifactSha256"),"snapshot hash not carried to claim");s.stagePreparing(info.taskId(),141,"convG2345678");s.result(info.taskId(),141,"convG2345678","Attached","ready");eq(s.taskInfo(info.taskId()).status(),"Attached","snapshot result not persisted");});
        test("snapshot auto-send reuses generic SendClicked and Sent lifecycle",()->{Path stateRoot=tmp.resolve("snapshot-send-state");StateStore st=new StateStore(stateRoot);Core core=new Core(st);core.setReviewDiffSendRetrySeconds(7);ChatBridgeService s=serviceWithChat(st,"convGS345678",142);Path zip=snapshotZip(tmp.resolve("snapshot-send.zip"));Core.ChatTaskInfo info=s.enqueueSnapshot(zip,"convGS345678",true);ok(info.autoSend(),"snapshot attach+send task did not freeze autoSend");Map<String,Object> claim=s.claim("convGS345678",142);eq(((Number)claim.get("sendRetryIntervalMs")).longValue(),7000L,"snapshot auto-send did not reuse the configured generic Send retry interval");s.stagePreparing(info.taskId(),142,"convGS345678");sendClicked(s,info.taskId(),142,"convGS345678");s.result(info.taskId(),142,"convGS345678","Sent","done");eq(s.taskInfo(info.taskId()).status(),"Sent","snapshot auto-send did not use generic Sent terminal truth");});
        test("same snapshot/chat keeps attach-only and attach+send as distinct actionable intents",()->{StateStore st=new StateStore(tmp.resolve("snapshot-mode-dedupe-state"));ChatBridgeService s=serviceWithChat(st,"convMode5678",143);Path zip=snapshotZip(tmp.resolve("snapshot-mode.zip"));Core.ChatTaskInfo attach=s.enqueueSnapshot(zip,"convMode5678",false),send=s.enqueueSnapshot(zip,"convMode5678",true);ok(!attach.taskId().equals(send.taskId()),"attach-only task was incorrectly reused for attach+send intent");eq(s.externalInteractions().size(),2,"distinct snapshot delivery intents were collapsed in External Interactions");});
        test("snapshot Send authorization closes the deadline race before the browser click",()->{StateStore st=new StateStore(tmp.resolve("snapshot-send-deadline-state"));ChatBridgeService s=new ChatBridgeService(st,1);s.replaceInventory(List.of(chat("convDead5678","Chat","https://chatgpt.com/c/convDead5678",144)));Path zip=snapshotZip(tmp.resolve("snapshot-send-deadline.zip"));Core.ChatTaskInfo task=s.enqueueSnapshot(zip,"convDead5678",true);s.claim("convDead5678",144);s.stagePreparing(task.taskId(),144,"convDead5678");s.stageSendArmed(task.taskId(),144,"convDead5678");Thread.sleep(1300);eq(s.taskInfo(task.taskId()).status(),"SendArmed","snapshot confirmation deadline rewrote an already-authorized guarded Send before the browser click");s.stageSendClicked(task.taskId(),144,"convDead5678");s.result(task.taskId(),144,"convDead5678","UnknownAfterSend","unconfirmed");});
